cd /workspace/mytests && python3 - <<'EOF'
import random, sys
sys.path.insert(0,'/workspace/project'); sys.path.insert(0,'/workspace/mytests')
from modules import byte_program as bp
from cmp_nodes import build_node
def naive(b):
    h=0
    for x in b: h=(h*257+x+1)&((1<<64)-1)
    return h
rnd=random.Random(4242)
bad=0
for trial in range(3000):
    L=rnd.randrange(0,80)
    data=bytes(rnd.randrange(256) for _ in range(L))
    node=build_node(data,rnd)
    assert node.n==len(data)
    if node.h != naive(data): bad+=1; print('hash mismatch',trial)
    for _ in range(5):
        lo=rnd.randrange(0,len(data)+1); hi=rnd.randrange(lo,len(data)+1)
        if bp.rhash(node,lo,hi)!=naive(data[lo:hi]): bad+=1; print('rhash mismatch',trial,lo,hi)
        if bytes(bp.read_bytes(node,lo,hi))!=data[lo:hi]: bad+=1; print('read mismatch',trial,lo,hi)
print('done bad=',bad)
EOF
